import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"审批与约束规则","description":"","frontmatter":{},"headers":[],"relativePath":"backend/approval.md","filePath":"backend/approval.md","lastUpdated":1791956973000}`),a={name:`backend/approval.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="审批与约束规则" tabindex="-1">审批与约束规则 <a class="header-anchor" href="#审批与约束规则" aria-label="Permalink to “审批与约束规则”">​</a></h1><p>菜单目录 <code>/approval</code> 下有两个页面，它们解决的是不同的问题，容易混淆：</p><table tabindex="0"><thead><tr><th>页面</th><th>归属</th><th>解决什么</th></tr></thead><tbody><tr><td><strong>审批中心</strong> <code>/approval/center</code></td><td>工作流模块</td><td><strong>单据审批</strong>：业务数据要人来批，一步或多级</td></tr><tr><td><strong>约束规则</strong> <code>/approval/constraint</code></td><td>Saas（<code>SysConstraintRule</code> + <code>SysConstraintRuleItem</code>）</td><td><strong>RBAC 约束引擎</strong>：授权本身合不合规</td></tr></tbody></table><h2 id="审批中心" tabindex="-1">审批中心 <a class="header-anchor" href="#审批中心" aria-label="Permalink to “审批中心”">​</a></h2><p>审批统一走 <a href="./workflow">工作流</a>：业务单据按「业务编码 = 流程编码、单据主键 = 实例业务相关性标识」挂到流程上，审批人按角色、部门、岗位、发起人主管等规则解析，在审批中心的「待我审批」里办理，流程结束时回调业务回写单据。</p><p>一步审批就是只有一个人工任务节点的流程；多级、会签、条件分支、超时自动处理、并行汇合都在同一套机制里，改流程只需在设计器里发新版本。业务怎么接入见 <a href="./workflow#审批业务接入">工作流 · 审批业务接入</a>。</p><div class="tip custom-block"><p class="custom-block-title">5.8.0 起不再有「系统审查」</p><p>早先 Saas 自带的通用审批单 <code>SysReview</code> / <code>SysReviewLog</code> 已撤掉，权限申请改由工作流审批。升级脚本删除两张旧表；存量的待审批权限申请没有对应流程，统一置为已撤回，申请人重新提交即走新流程。</p></div><h2 id="约束规则引擎" tabindex="-1">约束规则引擎 <a class="header-anchor" href="#约束规则引擎" aria-label="Permalink to “约束规则引擎”">​</a></h2><p>这套东西管的<strong>不是业务数据，而是权限本身</strong>：判断一次授权是否违反组织的合规规则。</p><div class="warning custom-block"><p class="custom-block-title">当前只执行静态职责分离（SSD）</p><p>规则可以按下面八类维护，但真正有代码评估的只有 <strong>SSD</strong>（目标为角色的规则），在三条授权写入路径上执行：分配角色（含角色成员批量调整、让绑定重新生效的改状态 / 改有效期）、调整角色继承、审批通过带角色的权限申请。其余类型目前只是可维护的规则数据，不会拦截任何操作；规则也不参与请求期鉴权。</p></div><p><code>SysConstraintRule</code> 的结构：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>默认</th></tr></thead><tbody><tr><td><code>RuleCode</code> / <code>RuleName</code></td><td>规则编码与名称</td><td>—</td></tr><tr><td><code>ConstraintType</code></td><td><strong>约束类型</strong>（见下表）</td><td><code>SSD</code></td></tr><tr><td><code>TargetType</code></td><td>约束对象类型（角色 / 权限 / …）</td><td><code>Role</code></td></tr><tr><td><code>Parameters</code></td><td>规则参数（JSON）；SSD 读 <code>maxAllowed</code>：同组内最多同时持有几个目标，缺省 1</td><td>—</td></tr><tr><td><strong><code>ViolationAction</code></strong></td><td><strong>违规时怎么处理</strong>（见下表）</td><td><code>Deny</code></td></tr><tr><td><code>Priority</code></td><td>优先级</td><td><code>0</code></td></tr><tr><td><code>EffectiveTime</code> / <code>ExpirationTime</code></td><td>生效时间窗</td><td>—</td></tr><tr><td><code>Status</code></td><td>启停</td><td><code>Enabled</code></td></tr></tbody></table><p><code>SysConstraintRuleItem</code> 是规则的目标项集合（如「这三个角色互斥」里的那三个角色）。</p><h3 id="八类约束" tabindex="-1">八类约束 <a class="header-anchor" href="#八类约束" aria-label="Permalink to “八类约束”">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>值</th><th>含义</th><th>典型场景</th><th>当前是否执行</th></tr></thead><tbody><tr><td><strong>SSD</strong> 静态职责分离</td><td>0</td><td>一个用户<strong>不能同时被授予</strong>这组角色</td><td>「制单员」与「审核员」不能是同一人</td><td>执行（见上）</td></tr><tr><td><strong>DSD</strong> 动态职责分离</td><td>1</td><td>可以都有，但<strong>同一会话内不能同时激活</strong></td><td>平时可切换身份，单次操作只能用一个</td><td>不执行：会话角色激活尚无写入口</td></tr><tr><td><strong>互斥约束</strong></td><td>2</td><td>指定对象互相排斥</td><td>两个权限不能共存</td><td>不执行</td></tr><tr><td><strong>基数约束</strong></td><td>3</td><td>数量上限</td><td>「超级管理员最多 3 人」</td><td>不执行；限制角色人数请用角色的成员上限 <code>MaxMembers</code></td></tr><tr><td><strong>先决条件</strong></td><td>4</td><td>授予 A 前必须先有 B</td><td>给「财务审批」前必须先有「财务查看」</td><td>不执行</td></tr><tr><td><strong>时间约束</strong></td><td>5</td><td>只在特定时间窗内有效</td><td>临时权限只在项目期内</td><td>不执行；授权绑定自带生效 / 失效时间</td></tr><tr><td><strong>位置约束</strong></td><td>6</td><td>按 IP 限制</td><td>财务操作只能在办公网</td><td>不执行</td></tr><tr><td><strong>自定义</strong></td><td>99</td><td>扩展点</td><td>—</td><td>不执行</td></tr></tbody></table><p>SSD 评估时展开角色继承链：规则指向角色 A，任何继承了 A 的角色都视为持有 A；停用的角色同样计入（随时可能重新启用）。</p><h3 id="四种违规处理" tabindex="-1">四种违规处理 <a class="header-anchor" href="#四种违规处理" aria-label="Permalink to “四种违规处理”">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>值</th><th>当前效果</th></tr></thead><tbody><tr><td><code>Deny</code> 拒绝</td><td>0</td><td>直接阻断，整次授权写入失败，错误信息带规则编码、名称与冲突角色主键</td></tr><tr><td><code>Warning</code> 警告</td><td>1</td><td>放行，写一条 Warning 级应用日志；不会提示操作人</td></tr><tr><td><code>Log</code> 记录日志</td><td>2</td><td>放行，同样写一条 Warning 级应用日志</td></tr><tr><td><code>RequireApproval</code> 需审批</td><td>3</td><td><strong>与 <code>Deny</code> 相同，直接阻断</strong>；不会生成审批单，也不会转入审批流程</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">上线新规则的姿势</p><p>直接上 <code>Deny</code> 风险很大——存量数据里往往已经有一批违规状态，一开就挡住相关人员之后的角色调整。</p><p>推荐路径：先用 <code>Log</code>（或 <code>Warning</code>，两者效果相同）跑一段时间，从应用日志里看有哪些授权命中了规则；清理完存量后再切 <code>Deny</code>。</p></div><div class="warning custom-block"><p class="custom-block-title">违规检查发生在授权写入时，不是登录或请求时</p><p>约束规则只回答「能不能把这个角色授给这个人」，不参与请求期的鉴权判定。已经授出去的存量违规组合<strong>不会自动回收</strong>，系统也没有内置巡检，需要自行排查清理。</p></div><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to “怎么选”">​</a></h2><table tabindex="0"><thead><tr><th>你的需求</th><th>用哪套</th></tr></thead><tbody><tr><td>业务单据要人批（一步或多级、会签、分支、超时）</td><td><strong>审批中心</strong>（由 <a href="./workflow">工作流</a> 承载）</td></tr><tr><td>「谁不能同时拥有哪些角色」这类合规规则</td><td><strong>约束规则引擎</strong></td></tr><tr><td>用户主动申请某个权限，管理员审批</td><td><strong>权限申请</strong>（<code>SysPermissionRequest</code>，提交即发起审批流，见 <a href="./permission">权限模型</a>）</td></tr></tbody></table><p>约束规则与审批彼此独立：约束规则的 <code>RequireApproval</code> 不会发起审批，命中即阻断；需要「违规转审批」时，可让申请人走权限申请，审批通过授予时同样会做 SSD 校验。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to “相关页面”">​</a></h2><ul><li><a href="./permission">权限模型</a>：约束规则的当前执行范围、权限申请与委托</li><li><a href="./workflow">工作流</a>：审批中心、受理人规则与审批业务接入</li><li><a href="./logging">审计日志</a>：权限变更留痕</li><li><a href="./data-model#权限与授权">数据模型</a>：相关表结构</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};